UPDATE students
SET total_point = total_point - #{amount}
WHERE (student_id = #{studentId} OR student_id = (SELECT CAST(id AS CHAR) FROM students WHERE student_id = #{studentId} LIMIT 1))

UPDATE students
SET total_point = total_point + #{amount}
WHERE (student_id = #{studentId} OR student_id = (SELECT CAST(id AS CHAR) FROM students WHERE student_id = #{studentId} LIMIT 1))
